// Hand-written `@trpc/client` stub for the flowatlas fixture suite.
//
// A client is made from a chain of links, and the last link of the chain is
// the one that sends: `loggerLink` passes a request on, `splitLink` hands it to
// one of two chains, `httpBatchLink` and `httpLink` send it to their URL, and
// `wsLink` sends it over a socket the WebSocket client opened. The typed client
// is what its type argument says, and a fixture hands it `any`, which is what a
// clone nobody installed looks like. The untyped client names the path as text.
//
// It declares less than the library: no transformers, no headers, no
// operation types. It declares nothing of a different kind.

export interface TRPCLink {
  readonly _link: true;
}

export interface Operation {
  readonly type: 'query' | 'mutation' | 'subscription';
  readonly path: string;
}

export declare function loggerLink(options?: unknown): TRPCLink;
export declare function httpBatchLink(options: { url: string | (() => string) }): TRPCLink;
export declare function httpLink(options: { url: string | (() => string) }): TRPCLink;
export declare function splitLink(options: {
  condition: (op: Operation) => boolean;
  true: TRPCLink | TRPCLink[];
  false: TRPCLink | TRPCLink[];
}): TRPCLink;
export declare function createWSClient(options: { url: string }): unknown;
export declare function wsLink(options: { client: unknown }): TRPCLink;

export declare function createTRPCClient<T = any>(options: { links: TRPCLink[] }): T;

export interface UntypedClient {
  query(path: string, input?: unknown): Promise<unknown>;
  mutation(path: string, input?: unknown): Promise<unknown>;
  subscription(path: string, input: unknown, options: { onData(data: unknown): void }): { unsubscribe(): void };
}

export declare function createTRPCUntypedClient(options: { links: TRPCLink[] }): UntypedClient;
